window.STORIES={"title": "重走抗联路", "subtitle": "林海中的信号", "designNote": "以“重走抗联路·林海中的信号”为主题，采用朱红、绛红与鎏金的经典配色，以书法标题、实景照片、金色路线、纪念章与时间轴串联三省一区的抗联记忆。依据两份台账构建精选研学路线与资料查询两层结构，保留原始核实状态。点击点位可读故事、核对史料并保存手记。红绸与金边强化庄重气质，让地图兼具路线导览、图像档案与精神传承的功能。", "routes": [{"id": "hlj", "code": "A", "region": "黑龙江", "name": "林海坚守", "question": "密营如何支撑长期斗争？", "sites": ["A1", "A2", "A3"], "summary": "哈尔滨 → 汤原 → 林口；跨市分段研学。"}, {"id": "jl", "code": "B", "region": "吉林", "name": "白山忠魂", "question": "从根据地到纪念地，信念如何延续？", "sites": ["B1", "B2", "B3"], "summary": "磐石 → 靖宇 → 通化；从根据地寻访走向英烈纪念。"}, {"id": "ln", "code": "C", "region": "辽宁", "name": "军民同心", "question": "军民协作如何维系抗联的生存？", "sites": ["C1", "C2", "C3"], "summary": "本溪小市 → 关门山 → 东营坊红通沟；县域专题研学。"}, {"id": "nmg", "code": "D", "region": "内蒙古东部", "name": "兴安回响", "question": "为什么要把纪念与地方记忆联系起来？", "sites": ["D1", "D2", "D3"], "summary": "那吉镇 → 三岔河镇 → 霍尔奇镇；阿荣旗专题研学。"}], "sites": [{"id": "A1", "route": "hlj", "name": "东北烈士纪念馆", "short": "东北烈士纪念馆", "county": "南岗区", "place": "黑龙江 · 哈尔滨市", "address": "哈尔滨市南岗区一曼街241号", "kind": "纪念馆", "tag": "读懂抗联", "story": "以馆藏文物与展览为入口，建立对东北抗联斗争的整体认识。把一个英烈的故事与一件文物联系起来，再带着问题走向遗址。", "task": "选一件展品，记录它的名称、用途和来源；写下它让你理解的一个历史细节。", "source": "https://wlt.hlj.gov.cn/wlt/c114253/202506/c00_31846825.shtml", "sourceName": "黑龙江省文化和旅游厅", "symbol": "馆"}, {"id": "A2", "route": "hlj", "name": "东北抗联密营遗址纪念馆", "short": "密营遗址纪念馆", "county": "汤原县", "place": "黑龙江 · 汤原县", "address": "大亮子河林场东北抗联六军军部遗址区域", "kind": "密营 / 纪念馆", "tag": "林海中的后方", "story": "汤原大亮子河的密营遗址呈现了抗联的后方生活。通过纪念馆与遗址，理解隐蔽、补给、医护与组织工作怎样相互支撑。", "task": "从展陈中找出三种密营功能，画出它们之间的关系；区分遗存与复原展示。", "source": "https://www.tangyuan.gov.cn/tyx/c102024/202512/c04_273509.shtml", "sourceName": "汤原县人民政府", "symbol": "营"}, {"id": "A3", "route": "hlj", "name": "“八女投江”殉难地", "short": "“八女投江”殉难地", "county": "林口县", "place": "黑龙江 · 林口县", "address": "刁翎镇三家子村附近乌斯浑河畔", "kind": "纪念地", "tag": "江河铭记", "story": "1938年，八位抗联女战士在乌斯浑河畔英勇牺牲。在纪念地阅读她们的名字与经历，让宏大的历史回到具体的人。", "task": "选一位女战士，查证她的姓名与经历，用100字讲述她的故事，并列出依据。", "source": "https://www.linkou.gov.cn/mdjlkxrmzf/zmjq548_LK/202402/c03_871998.shtml", "sourceName": "林口县人民政府", "symbol": "碑"}, {"id": "B1", "route": "jl", "name": "红石砬子抗日根据地遗址", "short": "红石砬子根据地", "county": "磐石市", "place": "吉林 · 磐石市", "address": "磐石市西侧红石砬子山区", "kind": "根据地遗址", "tag": "根据地的建立", "story": "红石砬子遗址中的房址、地窨子和工事，留下了抗联战斗与生活的证据。考古发现帮助我们理解根据地的组织方式。", "task": "观察一种遗迹，说明你看见了什么、能推断什么，以及还需要哪些证据。", "source": "https://whhlyt.jl.gov.cn/stdt/202212/t20221207_8645090.html", "sourceName": "吉林省文化和旅游厅", "symbol": "址"}, {"id": "B2", "route": "jl", "name": "杨靖宇将军殉国地", "short": "杨靖宇将军殉国地", "county": "靖宇县", "place": "吉林 · 靖宇县", "address": "靖宇县三道崴子", "kind": "纪念地", "tag": "1940 · 坚守", "story": "1940年2月23日，杨靖宇在三道崴子壮烈牺牲。这里承载着他在极端艰难条件下坚持抗日的最后记忆。", "task": "查阅两份关于杨靖宇的资料，整理时间、地点与事件；将史实与个人感受分别记录。", "source": "https://cpc.people.com.cn/n1/2025/0826/c443712-40550173.html", "sourceName": "中国共产党新闻网", "symbol": "碑"}, {"id": "B3", "route": "jl", "name": "杨靖宇烈士陵园", "short": "杨靖宇烈士陵园", "county": "东昌区", "place": "吉林 · 通化市", "address": "通化市靖宇路888号", "kind": "烈士陵园 / 纪念馆", "tag": "铭记与传承", "story": "通化杨靖宇烈士陵园暨东北抗日联军纪念馆，将英烈纪念与历史学习联系起来。研学在此从知识整理走向对责任与信念的思考。", "task": "以“我从一处遗址读懂了什么”为题，写一段研学感想，并引用一个已核实的事实。", "source": "https://yjylsly.org.cn/", "sourceName": "杨靖宇烈士陵园官网", "symbol": "陵"}, {"id": "C1", "route": "ln", "name": "东北抗联史实陈列馆", "short": "抗联史实陈列馆", "county": "本溪满族自治县", "place": "辽宁 · 本溪满族自治县", "address": "小市镇滨河东路", "kind": "纪念馆", "tag": "辽东抗联", "story": "本溪东北抗联史实陈列馆系统展示抗联斗争。先在馆内建立事件与人物的联系，再到县域遗址理解历史发生的空间。", "task": "制作一张“人物—地点—事件”关系卡，标明每条信息来自哪一块展板或哪份史料。", "source": "https://bx.benxi.gov.cn/fxly/lyjd/content_357277", "sourceName": "本溪满族自治县人民政府", "symbol": "馆"}, {"id": "C2", "route": "ln", "name": "关门山抗联交通站及密营遗址", "short": "关门山交通站及密营", "county": "本溪满族自治县", "place": "辽宁 · 本溪满族自治县", "address": "关门山内，密营展示位于鸣翠谷", "kind": "交通站 / 密营", "tag": "隐蔽的补给网络", "story": "关门山交通站连接地方群众与抗联部队。现有密营群落展示含在原遗址附近恢复重建的设施，阅读现场标识时需要区分遗址与复建。", "task": "画一条“群众—交通站—密营”的补给关系线，并在观察记录中注明复建展示。", "source": "https://www.czkll.cn/news/705.html", "sourceName": "本溪抗联史实教育基地", "symbol": "营"}, {"id": "C3", "route": "ln", "name": "东北抗联第一军第二次西征会议遗址", "short": "第二次西征会议遗址", "county": "本溪满族自治县", "place": "辽宁 · 本溪满族自治县", "address": "东营坊红土甸子红通沟", "kind": "会议遗址", "tag": "在困境中寻找方向", "story": "第二次西征会议遗址是理解抗联一军行动决策的学习节点。将会议信息放回当时的斗争环境，思考决策所面对的困难。", "task": "围绕“为什么西征”提出两个问题，查找可支持或修正你理解的史料。", "source": "https://www.ln.gov.cn/web/sqgk/whly/jplx/2025101414530721816/", "sourceName": "辽宁省人民政府", "symbol": "址"}, {"id": "D1", "route": "nmg", "name": "呼伦贝尔东北抗联纪念馆", "short": "呼伦贝尔抗联纪念馆", "county": "阿荣旗", "place": "内蒙古东部 · 阿荣旗", "address": "那吉镇东山抗联英雄园内", "kind": "纪念馆 / 纪念园", "tag": "兴安抗联记忆", "story": "阿荣旗抗联英雄园与呼伦贝尔东北抗联纪念馆，讲述抗联在兴安地区的斗争。这里是了解地方群众支持抗联的重要入口。", "task": "找一个军民协作的故事，标出参与者、行动和历史背景，并注明资料来源。", "source": "https://nmgqq.com.cn/xuanchuanjiaoyu/yizhiyiji/hulunbeiershi/2023-09-19/29729.html", "sourceName": "内蒙古自治区党委党史和地方志研究室", "symbol": "馆"}, {"id": "D2", "route": "nmg", "name": "冯治纲将军殉难处纪念碑", "short": "冯治纲殉难处纪念碑", "county": "阿荣旗", "place": "内蒙古东部 · 阿荣旗", "address": "三岔河镇韭菜沟村任家屯后山", "kind": "纪念碑", "tag": "远征中的牺牲", "story": "1940年2月4日，冯治纲在阿荣旗战斗中牺牲。殉难处纪念碑与地方的守护记忆，让远征故事获得具体的历史坐标。", "task": "记录碑名与纪念对象，把碑文信息与纪念馆资料交叉核对。", "source": "https://www.krzzjn.com/show-1030-112918.html", "sourceName": "抗日战争纪念网 · 转载内蒙古党史网", "symbol": "碑"}, {"id": "D3", "route": "nmg", "name": "高禹民七烈士牺牲地纪念碑", "short": "高禹民七烈士纪念碑", "county": "阿荣旗", "place": "内蒙古东部 · 阿荣旗", "address": "霍尔奇镇顺利村永和组一带", "kind": "纪念碑", "tag": "掩护与坚守", "story": "1940年11月30日，高禹民等七名抗联指战员在阿荣旗壮烈牺牲。将纪念碑与相关史料对读，理解掩护战友突围的历史情境。", "task": "用一段文字解释“掩护”意味着什么，以核实的史实为依据，避免虚构对话。", "source": "https://www.nmgqq.com.cn/zhuantiwangzhan/jnkz/neimenggudiqukangzhanzhuanlan/2025-09-04/431653.html", "sourceName": "内蒙古自治区党委党史和地方志研究室", "symbol": "碑"}], "timeline": [{"year": "1932", "title": "根据地 · 星火", "text": "红石砬子抗日根据地创建。遗迹与考古材料让战斗、生活和组织的历史可被阅读。", "site": "B1"}, {"year": "1938", "title": "江河 · 铭记", "text": "八位抗联女战士在乌斯浑河畔英勇牺牲。历史由具体的姓名与生命构成。", "site": "A3"}, {"year": "1940", "title": "坚守 · 忠魂", "text": "杨靖宇在靖宇县三道崴子壮烈牺牲。循着遗址与纪念地，追问信念的力量。", "site": "B2"}, {"year": "今天", "title": "寻访 · 传承", "text": "沿当代研学建议线走进纪念馆与遗址，将观察、史料与思考整理成个人研学手记。", "site": "B3"}]};